    payload = {
        "model": JEV_MODEL,
        "state": guardrail,
        "questions": {
            "category": {
                "type": "choice",
                "instructions": (
                    "Which category best describes this guardrail? "
                    "Choose exactly one category based on the guardrail's meaning."
                ),
                "criteria": categories
            }
        }
    }

    response = requests.post(
        OPENROUTER_API_URL,
        headers=_authorization_headers(),
        json=payload,
        timeout=60
    )

    response.raise_for_status()

    data = response.json()

