    answer = data["answers"]["category"]

    return {
        "category": answer.get("choice"),
        "confidence": answer.get("confidence"),
        "probabilities": answer.get("probabilities"),
        "usage": data.get("usage", {})
    }


def classify_guardrails_batch(
    guardrails: list[dict[str, str]],
    categories: dict[str, str],
    context: str,
) -> dict[str, Any]:
    if not guardrails:
        raise ValueError("A JEV batch must contain at least one guardrail.")

    questions = {
        item["question_id"]: {
            "type": "choice",
            "instructions": (
                "Which category best describes the guardrail in the state "
                f"whose question_id is {item['question_id']}? Choose exactly "
                "one category based on the guardrail's meaning."
            ),
            "criteria": categories,
        }
        for item in guardrails
    }
    payload = {
        "model": JEV_MODEL,
        "state": {
            "context": context,
            "guardrails": [
                {
                    "question_id": item["question_id"],
                    "guardrail_id": item["guardrail_id"],
                    "text": item["text"],
                }
                for item in guardrails
            ],
        },
        "questions": questions,
    }

    response = requests.post(
        OPENROUTER_API_URL,
        headers=_authorization_headers(),
        json=payload,
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()

    return {
        "answers": data.get("answers", {}),
        "usage": data.get("usage", {}),
    }


def detect_metadata_batch(
    sources: list[dict[str, str]],
    options_by_field: dict[str, dict[str, str]],
) -> dict[str, Any]:
    if not sources:
        raise ValueError("JEV metadata detection requires at least one source.")

    field_instructions = {
        "brand": (
            "Choose the brand or product name explicitly supported by the "
            "provided material. Do not select an agency, person, or "
            "organization unless it is clearly the brand. If none is clear, "
            "choose 'No brand found'."
        ),
        "market": (
            "Choose the country or market explicitly supported by the "
            "provided material. If none is clear, choose 'No market found'."
        ),
        "asset_type": (
            "Choose the type of content or asset explicitly supported by the "
            "provided material. If none is clear, choose 'No asset type found'."
        ),
    }
    questions: dict[str, dict[str, Any]] = {}
    for field, options in options_by_field.items():
        if field not in field_instructions:
            raise ValueError(f"Unsupported JEV metadata field: {field}.")
        instructions = field_instructions[field]
        fallback = {
            "brand": "No brand found",
            "market": "No market found",
            "asset_type": "No asset type found",
        }[field]
        criteria = dict(options)
        criteria.setdefault(fallback, "No clear evidence for this field.")
        questions[field] = {
            "type": "choice",
            "instructions": instructions,
            "criteria": criteria,
        }

    if not questions:
        raise ValueError("JEV metadata batch requires at least one field.")
    payload = {
        "model": JEV_MODEL,
        "state": {"sources": sources},
        "questions": questions,
    }
    try:
        response = requests.post(
            OPENROUTER_API_URL,
            headers=_authorization_headers(),
            json=payload,
            timeout=(8, 25),
        )
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as exc:
        raise ValueError(f"JEV metadata batch request failed: {exc}") from exc
    except (ValueError, KeyError, TypeError) as exc:
        raise ValueError(f"JEV metadata batch response was invalid: {exc}") from exc

    answers = data.get("answers")
    if not isinstance(answers, dict):
        raise ValueError("JEV metadata batch response did not contain answers.")
    return {"answers": answers, "usage": data.get("usage", {})}

import { useState } from "react";
import UploadPanel from "./UploadPanel";
import CategoryEditor from "./CategoryEditor";
import ResultsTable from "./ResultsTable";
import EngineSummary from "./EngineSummary";
import type { Category, EngineState, JevMode, JevResultRow, UploadResponse } from "../types";

interface JevPanelProps {
  fileInfo: UploadResponse | null;
  onUploaded: (response: UploadResponse) => void;
  categories: Category[];
  onCategoriesChange: (categories: Category[]) => void;
  context: string;
  onContextChange: (context: string) => void;
  engine: EngineState<JevResultRow>;
  onRunFull: (limit: number | null, mode: JevMode) => Promise<void>;
}

export default function JevPanel({
  fileInfo,
  onUploaded,
  categories,
  onCategoriesChange,
  context,
  onContextChange,
  engine,
  onRunFull,
}: JevPanelProps) {
  const [activeRun, setActiveRun] = useState<"custom" | "all" | null>(null);
  const [customLimit, setCustomLimit] = useState("20");
  const [mode, setMode] = useState<JevMode>("normal");
  const running = engine.status === "running";
  const hasCategories = categories.some((c) => c.name.trim() !== "");
  const disabled = !fileInfo || !hasCategories;

  async function handleRun(limit: number | null) {
    setActiveRun(limit === null ? "all" : "custom");
    try {
      await onRunFull(limit, mode);
    } finally {
      setActiveRun(null);
    }
  }

  return (
    <div className="card engine-panel engine-panel-jev">
      <div className="engine-panel-header">
        <span className="status-dot status-dot-jev" />
        <span className="engine-title">Jev · typed Choice</span>
        <span className="pill pill-jev">deterministic</span>
      </div>

      <UploadPanel fileInfo={fileInfo} onUploaded={onUploaded} />

      <div className="field-block">
        <label className="field-label">Context / state</label>
        <textarea
          className="input textarea"
          placeholder="e.g. audience=HCP, channel=email, market=US"
          rows={4}
          value={context}
          onChange={(e) => onContextChange(e.target.value)}
        />
      </div>

      <CategoryEditor categories={categories} onChange={onCategoriesChange} />

      <fieldset className="jev-mode-switch" disabled={running}>
        <legend className="field-label">JEV run mode</legend>
        <label className={mode === "normal" ? "jev-mode-option selected" : "jev-mode-option"}>
          <input
            type="radio"
            name="jev-run-mode"
            value="normal"
            checked={mode === "normal"}
            onChange={() => setMode("normal")}
          />
          <span>Normal</span>
          <small>One request per guardrail</small>
        </label>
        <label className={mode === "batch" ? "jev-mode-option selected" : "jev-mode-option"}>
          <input
            type="radio"
            name="jev-run-mode"
            value="batch"
            checked={mode === "batch"}
            onChange={() => setMode("batch")}
          />
          <span>Batch</span>
          <small>Groups using settings.txt batch size</small>
        </label>
      </fieldset>

      <div className="run-controls">
        <div className="field-block run-count-field">
          <label className="field-label" htmlFor="jev-custom-count">
            Guardrails to classify
          </label>
          <input
            id="jev-custom-count"
            className="input run-count-input"
            type="number"
            min={1}
            max={fileInfo?.total_guardrails ?? undefined}
            value={customLimit}
            onChange={(event) => setCustomLimit(event.target.value)}
          />
        </div>
        <button
          type="button"
          className="btn btn-primary"
          disabled={
            disabled ||
            running ||
            !Number.isInteger(Number(customLimit)) ||
            Number(customLimit) < 1 ||
            Number(customLimit) > (fileInfo?.total_guardrails ?? 0)
          }
          onClick={() => void handleRun(Number(customLimit))}
        >
          {running && activeRun === "custom" ? "Running custom…" : "Run custom →"}
        </button>
        <button
          type="button"
          className="btn btn-outline run-all-button"
          disabled={disabled || running}
          onClick={() => void handleRun(null)}
        >
          {running && activeRun === "all" ? "Running all…" : "Run all guardrails →"}
        </button>
      </div>

      {engine.error && <p className="error-text">{engine.error}</p>}

      {engine.status === "running" && (
        <div className="jev-run-progress">
          <p className="muted">
            {engine.progress
              ? `${engine.progress.status === "queued" ? "Queued" : "Processing"} JEV run in ${engine.progress.mode} mode${engine.progress.mode === "batch" ? ` (batch size ${engine.progress.batch_size})` : ""}: ${engine.progress.completed}${engine.progress.total_rows == null ? "" : `/${engine.progress.total_rows}`} rows checked, ${engine.progress.processed} classified, ${engine.progress.failed} failed.`
              : "Starting JEV run…"}
          </p>
          {engine.progress?.total_rows != null && (
            <progress
              className="jev-progress-bar"
              max={Math.max(engine.progress.total_rows, 1)}
              value={engine.progress.completed}
              aria-label="Full JEV classification progress"
            />
          )}
        </div>
      )}

      {engine.status === "done" && (
        <div className="muted">
          {engine.results.length} rows classified in {((engine.elapsedMs ?? 0) / 1000).toFixed(1)}s
          {engine.runMode &&
            ` (${engine.runMode} mode${engine.runMode === "batch" ? `, batch size ${engine.batchSize}` : ""})`}
          {!!engine.failedCount && `; ${engine.failedCount} rows failed`}
          {engine.usageNote && <p>{engine.usageNote}</p>}
        </div>
      )}

      {engine.status === "done" && (
        <EngineSummary
          rows={engine.results}
          categories={categories.map((category) => category.name.trim()).filter(Boolean)}
          elapsedMs={engine.elapsedMs ?? 0}
          engine="jev"
        />
      )}

      <ResultsTable
        rows={engine.results}
        rowKey={(row) => row.GuardrailId}
        emptyText="Run to see results"
        columns={[
          { header: "ID", render: (r) => r.GuardrailId },
          { header: "Rule", render: (r) => r.ShortRule },
          { header: "Category", render: (r) => r.JEV_Category },
          {
            header: "Confidence",
            render: (r) => (r.JEV_Confidence != null ? r.JEV_Confidence.toFixed(2) : "—"),
          },
        ]}
      />
    </div>
  );
}

