export async function runJevFull(
  fileId: string,
  categories: { name: string; description: string }[],
  context: string,
  limit: number | null,
  onProgress: (progress: RunProgress) => void
): Promise<{
  results: JevResultRow[];
  batch_size: number;
  failed: number;
  usage_note?: string;
}> {
  const job = await request<{
    job_id: string;
    batch_size: number;
    total_rows: number | null;
    completed: number;
    processed: number;
    failed: number;
    status: "queued" | "running";
  }>(`/classify/${fileId}/run`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      categories: categoriesAsDict(categories),
      context,
      limit: limit ?? 0,
    }),
  });

  const reportProgress = (status: {
    status: "queued" | "running";
    batch_size: number;
    total_rows: number | null;
    completed: number;
    processed: number;
    failed: number;
  }) => {
    onProgress({
      status: status.status,
      batch_size: status.batch_size,
      total_rows: status.total_rows,
      completed: status.completed,
      processed: status.processed,
      failed: status.failed,
    });
  };

  reportProgress(job);
  while (true) {
    await new Promise((resolve) => window.setTimeout(resolve, 750));
    const status = await request<{
      status: "queued" | "running" | "done" | "error";
      batch_size: number;
      total_rows: number | null;
      completed: number;
      processed: number;
      failed: number;
      job_id: string;
      results?: JevResultRow[];
      error?: string;
      usage_note?: string;
    }>(`/classify/${fileId}/run/${job.job_id}`);

    if (status.status === "queued") {
      reportProgress({ ...status, status: "queued" });
      continue;
    }
    if (status.status === "running") {
      reportProgress({ ...status, status: "running" });
      continue;
    }
    if (status.status === "error") {
      throw new Error(status.error ?? "Full JEV classification failed.");
    }
    return {
      results: status.results ?? [],
      batch_size: status.batch_size,
      failed: status.failed,
      usage_note: status.usage_note,
    };
  }
}

